			SELECT CHECK_IN, CHECK_OUT, USER_NAME, USER_EMAIL, USER_PHONE
 			  FROM CAMP_RESERVATION_TBL
 			 WHERE USER_NAME=#{userName}
 			   AND USER_EMAIL=#{userEmail}
 			   AND USER_PHONE=#{userPhone}
 			   AND CHECK_IN=#{checkIn}
 			   AND CHECK_OUT=#{checkOut}

			SELECT CHECK_IN, CHECK_OUT, USER_NAME, USER_EMAIL, USER_PHONE
 			  FROM CAMP_RESERVATION_TBL
